cd "/c/Users/Jaidityaa Jain/OneDrive/Desktop/TechSparks" && python -I -c "
import re
tab=open('research_notes/dtx-story/S1-fact-homes.md',encoding='utf-8').read()
homes={}
for m in re.finditer(r'^\| (D\d-\d\d-F\d+) \| ([A-H]) \|',tab,re.M):
    homes[m.group(1)]=m.group(2)
def norm(i):
    a,b,c=i.split('-'); return f'{a}-{b}-F{int(c[1:])}'
fa=open('report-parts/dtx-story/81-app-a.md',encoding='utf-8').read()
fb=open('report-parts/dtx-story/82-app-b.md',encoding='utf-8').read()
ida={norm(x) for x in re.findall(r'D\d-\d\d-F\d+',fa)}
idb={norm(x) for x in re.findall(r'D\d-\d\d-F\d+',fb)}
both=ida|idb
for L in 'AB':
    want={k for k,v in homes.items() if v==L}
    print(L,'total',len(want),'placed',len(want&both),'missing',sorted(want-both))
    print('  in A file',len(want&ida),'in B file',len(want&idb))
other=sorted((both)-{k for k,v in homes.items() if v in 'AB'})
print('other-home IDs used:',[(o,homes.get(o,'NOT IN TABLE')) for o in other])
for name,t in (('A',fa),('B',fb)):
    print(name,'words',len(t.split()))
    for pat in ['—','–','!','\\?','Imagine','synergy','revolutionary','game-changing','AI-powered','seamless','leverage','utilise','robust','cutting-edge','innovative','streamline','optimise','empower','unlock','world-class','best-in-class','next-gen','ecosystem','landscape','holistic','delve','solution','compliant','100%','zero risk','/mo']:
        n=len(re.findall(pat,t,re.I))
        if n: print('  ',repr(pat),n)
    bad=re.findall(r'\[[^\]]*D\d-\d\d-F\d(?!\d)[^\]]*\]',t)
    print('  single-digit IDs:',bad[:5])
"

