import re
tab=open('research_notes/dtx-story/S1-fact-homes.md',encoding='utf-8').read()
homes={m.group(1):m.group(2) for m in re.finditer(r'^\| (D\d-\d\d-F\d+) \| ([A-H]) \|',tab,re.M)}
def norm(i):
    a,b,c=i.split('-'); return f'{a}-{b}-F{int(c[1:])}'
fa=open('report-parts/dtx-story/81-app-a.md',encoding='utf-8').read()
fb=open('report-parts/dtx-story/82-app-b.md',encoding='utf-8').read()
ida={norm(x) for x in re.findall(r'D\d-\d\d-F\d+',fa)}
idb={norm(x) for x in re.findall(r'D\d-\d\d-F\d+',fb)}
print('A-home only in B file:',sorted(k for k,v in homes.items() if v=='A' and k in idb and k not in ida))
print('B-home only in A file:',sorted(k for k,v in homes.items() if v=='B' and k in ida and k not in idb))
# IDs in old source parts that are A/B home but check source parts IDs not placed at all
src=''.join(open('report-parts/dtx/'+f,encoding='utf-8').read() for f in ['10-challenge.md','20-burden.md','25-voice.md','30-doctor.md','35-scale.md'])
ids={norm(x) for x in re.findall(r'D\d-\d\d-F\d+',src)}
print('source IDs not placed anywhere:',sorted((ids-ida-idb), key=lambda k:(k, homes.get(k))), [homes.get(k) for k in sorted(ids-ida-idb)])
print('em/en dash count', fa.count('—')+fb.count('—'), fa.count('–')+fb.count('–'))
print('qmarks', fa.count('?'), fb.count('?'))
for m in re.finditer(r'.{60}utilise.{20}',fb): print(m.group(0))
"

